import 'governance_models.dart';
abstract interface class GovernanceRepository { Future<GovernanceSnapshot> load(); Future<PolicyPack> createBaselinePolicy(String name); Future<PolicyPack> setPolicyActive(String id,{required bool active}); Future<void> createRoleTemplate(String name,List<String> permissions); Future<void> createApprovalRule(String name,String pattern,{int minimumApprovers=1,List<String> requiredRoles=const['owner']}); Future<void> updateMemoryGovernance({required int retentionDays,required bool allowPermanent,required bool requireProvenance,List<String> sourceTypes=const[]}); Future<void> upsertMarketplacePackage(MarketplaceItem item); Future<void> deleteMarketplacePackage(String id); Future<void> installPackage(String id); Future<void> uninstallPackage(String id); Future<RoutingTarget> updateTarget(RoutingTarget target); Future<void> exportAudit(String format); }
class GovernanceOfflineException implements Exception { const GovernanceOfflineException(this.message);final String message; }
